import 'dart:convert';
import 'dart:io';

/// Keep startup usable synchronously and offline, including on a fresh install.
void main() {
  final ui = jsonEncode(
    jsonDecode(File('assets/localization/ui.json').readAsStringSync()),
  );
  final languages = jsonEncode(
    jsonDecode(File('assets/localization/languages.json').readAsStringSync()),
  );
  if (ui.contains("'''") || languages.contains("'''")) {
    throw const FormatException('Unsupported literal');
  }
  File('lib/core/localization/bundled_localization.dart').writeAsStringSync(
    "// Generated by dart run tool/generate_localization.dart.\n"
    "const bundledUiJson = r'''$ui''';\n"
    "const bundledLanguagesJson = r'''$languages''';\n",
  );
}
